import{_ as l,l as r,o as e,c,v as o,p as d,x as t,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"逻辑复制与 CDC","description":"","frontmatter":{"title":"逻辑复制与 CDC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/logical-replication-cdc.md","filePath":"cs/logical-replication-cdc.md","lastUpdated":1789023840000}'),E={name:"cs/logical-replication-cdc.md"};function C(D,a,h,_,A,u){const i=r("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="逻辑复制与-cdc" tabindex="-1">逻辑复制与 CDC <a class="header-anchor" href="#逻辑复制与-cdc" aria-label="Permalink to &quot;逻辑复制与 CDC&quot;">​</a></h1><div class="epigraph"><p>从 WAL 解出行级变化流：下游可异构、可过滤表。这是逻辑日志的消费者，不是备库再应用生理 redo。</p><footer>—— 据 Postgres logical decoding；Gray；CDC 实践；日志粒度课落地</footer></div><p><a href="/cs/backup-pitr">上一课</a>把 WAL 当 PITR 原料。本课把同一 WAL（或触发器）当成变化数据捕获（CDC）流。主干 <a href="/cs/replication-log">复制与日志传送</a> 偏物理。进阶：逻辑复制解码成 <code>INSERT/UPDATE/DELETE</code> 行像，给搜索索引、数仓、缓存。半同步下一课仍偏物理耐久。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理复制：同引擎、同版本、全库页。逻辑：表子集、转换、多下游。缺口是<strong>解码与槽</strong>：保持解码所需的 WAL 与旧行像（undo/堆版本），槽不消费则磁盘涨——与 MVCC 水位同一类钉子。顺序：事务提交序要在流里可见，否则下游聚合错。</p><p>全量+增量：先快照再从 LSN 接流，避免漏。DDL：逻辑流对模式演化敏感，迁移课的兼容窗口在此显现。</p><p><span class="marginnote">PostgreSQL logical decoding、MySQL binlog 行模式。Debezium 一类是生态。本课机制。无虚构论文号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输出插件：把事务变化写成 JSON/protobuf。下游幂等：用 LSN 或主键+版本去重。恰好一次后课流系统再谈；库侧至少 at-least-once 加幂等键。</p><p>过滤：只发某些表，减少流量。大对象可跳过或另通道。</p>',10)),(e(),d(p,null,{default:t(()=>[s(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAL%5B%22%E7%94%9F%E7%90%86%20WAL%22%5D%20--%3E%20DEC%5B%22%E9%80%BB%E8%BE%91%E8%A7%A3%E7%A0%81%22%5D%0A%20%20DEC%20--%3E%20SLOT%5B%22%E5%A4%8D%E5%88%B6%E6%A7%BD%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20SLOT%20--%3E%20DOWN%5B%22%E4%B8%8B%E6%B8%B8%E5%BC%82%E6%9E%84%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20DOWN%20--%3E%20ACK%5B%22%E6%8E%A8%E8%BF%9B%E6%A7%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>性能：解码 CPU、undo 读旧像。长事务一个大包提交时下游突发。与 SSI/锁无关直接，但未提交变化不应出现在流（按提交）。</p><p>冲突：多源写入下游要合并策略，本课单源。双向复制是另一事故源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲半同步 ACK。也不把 CDC 当 2PC。搜索引擎索引常用 CDC 填倒排。</p><p>后课默认：异构下游用逻辑 CDC+槽；同构 HA 用物理。半同步复制：提交等备库确认，换 RPO。</p><p>槽是消费者的 xmin，忘记 drop slot 会胀爆磁盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑复制从 WAL 解码行流，槽钉水位。</li><li>接流要快照对齐；DDL 要合同。</li><li>半同步复制下一课。</li><li>出处：logical decoding；Gray；CDC 实践。</li></ul>',9))])}const f=l(E,[["render",C]]);export{m as __pageData,f as default};
